check_dependencies <- function() {
 needed <- c('dplyr','tidyr','stringr','readr','ggplot2'); missing <- needed[!vapply(needed,requireNamespace,logical(1),quietly=TRUE)]; if(length(missing))stop(paste(missing,collapse=', ')); invisible(TRUE)
}
validate_history <- function(x) {
 required <- c('end_month_utc','artist','title','ms_played');if(!is.data.frame(x)||!all(required %in% names(x)))stop('Missing required history columns');x<-x[required];if(!nrow(x))stop('History is empty');for(nm in required[1:3]){if(!is.character(x[[nm]])||anyNA(x[[nm]])||any(!nzchar(trimws(x[[nm]]))))stop('Invalid text column: ',nm)}
 if(any(!grepl('^[0-9]{4}-(0[1-9]|1[0-2])$',x$end_month_utc)))stop('Invalid YYYY-MM month');if(!is.numeric(x$ms_played)||anyNA(x$ms_played)||any(!is.finite(x$ms_played))||any(x$ms_played<0)||any(x$ms_played!=floor(x$ms_played)))stop('ms_played must contain finite nonnegative whole numbers');x
}
read_history <- function(path){x<-readr::read_csv(path,col_types=readr::cols(end_month_utc=readr::col_character(),artist=readr::col_character(),title=readr::col_character(),ms_played=readr::col_double()),na=character(),show_col_types=FALSE);if(nrow(readr::problems(x)))stop('CSV parsing problems');validate_history(x)}
prepare_history <- function(x){x<-validate_history(x);x$known<-tolower(trimws(x$artist))!='unknown artist' & tolower(trimws(x$title))!='unknown track';pairs<-dplyr::distinct(x[x$known,],artist,title);pairs$pair_id<-seq_len(nrow(pairs));events<-dplyr::left_join(x[x$known,],pairs,by=c('artist','title'));audit<-data.frame(records=nrow(x),known_records=nrow(events),excluded_records=sum(!x$known),distinct_pairs=nrow(pairs),total_ms=sum(x$ms_played),excluded_ms=sum(x$ms_played[!x$known]));if(!nrow(events))stop('No known records');list(events=events,pairs=pairs,audit=audit)}
title_tokens<-function(pairs){words<-stringr::str_extract_all(stringr::str_to_lower(pairs$title,locale='en'),'[\\p{L}\\p{M}]+');z<-data.frame(pair_id=rep(pairs$pair_id,lengths(words)),word=as.character(unlist(words,use.names=FALSE)));dplyr::distinct(z,pair_id,word)}
primary_presence<-function(events,pairs,tokens,words,min_ms=30000){scopes<-list(all=events,at_least_30s=events[events$ms_played>=min_ms,]);dplyr::bind_rows(lapply(names(scopes),function(scope){e<-scopes[[scope]];ids<-unique(e$pair_id);dplyr::bind_rows(lapply(words,function(w){hit<-tokens$pair_id[tokens$word==w];data.frame(scope=scope,word=w,weighting=c('Distinct pairs','Listening records'),numerator=c(sum(ids %in% hit),sum(e$pair_id %in% hit)),denominator=c(length(ids),nrow(e)))}))})) |> dplyr::mutate(proportion=dplyr::if_else(denominator>0,numerator/denominator,NA_real_))}
word_salience<-function(events,pairs,tokens,cfg){f<-dplyr::count(events,pair_id,name='records');z<-dplyr::left_join(tokens,f,by='pair_id');z<-dplyr::summarise(dplyr::group_by(z,word),title_pairs=dplyr::n(),records=sum(records),.groups='drop');z<-z[!z$word %in% c(cfg$stopwords,cfg$metadata_words)&z$title_pairs>=cfg$salience_min_pairs&stringr::str_length(z$word)>=cfg$content_min_chars,];a<-cfg$smoothing;z$pair_proportion<-(z$title_pairs+a)/(nrow(pairs)+2*a);z$record_proportion<-(z$records+a)/(nrow(events)+2*a);z$log2_ratio<-log2(z$record_proportion/z$pair_proportion);dplyr::arrange(z,dplyr::desc(log2_ratio),word)}
js_divergence<-function(p,q){if(!is.numeric(p)||!is.numeric(q)||length(p)!=length(q)||!length(p)||any(!is.finite(c(p,q)))||any(c(p,q)<0))stop('Invalid aligned mass vectors');if(sum(p)==0||sum(q)==0)return(NA_real_);p<-p/sum(p);q<-q/sum(q);m<-(p+q)/2;kl<-function(a)sum(a[a>0]*log2(a[a>0]/m[a>0]));(kl(p)+kl(q))/2}
monthly_drift<-function(events,tokens,cfg){freq<-dplyr::count(tokens,word,name='pairs');vocabulary<-sort(freq$word[freq$pairs>=cfg$drift_min_pairs&stringr::str_length(freq$word)>=cfg$content_min_chars&!freq$word %in% c(cfg$stopwords,cfg$metadata_words)]);months<-format(seq(as.Date(paste0(min(events$end_month_utc),'-01')),as.Date(paste0(max(events$end_month_utc),'-01')),by='month'),'%Y-%m');f<-dplyr::count(events,end_month_utc,pair_id,name='records');w<-dplyr::inner_join(f,tokens[tokens$word %in% vocabulary,],by='pair_id',relationship='many-to-many');w<-dplyr::summarise(dplyr::group_by(w,end_month_utc,word),mass=sum(records),.groups='drop');mass<-matrix(0,nrow=length(months),ncol=length(vocabulary),dimnames=list(months,vocabulary));if(nrow(w))mass[cbind(match(w$end_month_utc,months),match(w$word,vocabulary))]<-w$mass
 compare_composition<-function(a,b,field){lev<-union(a[[field]],b[[field]]);if(!length(lev))return(NA_real_);js_divergence(tabulate(match(a[[field]],lev),length(lev)),tabulate(match(b[[field]],lev),length(lev)))}
 result<-dplyr::bind_rows(lapply(seq_along(months)[-1],function(i){a<-events[events$end_month_utc==months[i-1],];b<-events[events$end_month_utc==months[i],];boundary<-(i-1==1L||i==length(months));data.frame(previous_month=months[i-1],month=months[i],previous_records=nrow(a),records=nrow(b),boundary_comparison=boundary,include_comparison=!(cfg$exclude_boundary_months&&boundary),vocabulary_jsd=if(length(vocabulary))js_divergence(mass[i-1,],mass[i,])else NA_real_,pair_composition_jsd=compare_composition(a,b,'pair_id'),artist_composition_jsd=compare_composition(a,b,'artist'))}));if(!nrow(result))result<-data.frame(previous_month=character(),month=character(),previous_records=integer(),records=integer(),boundary_comparison=logical(),include_comparison=logical(),vocabulary_jsd=double(),pair_composition_jsd=double(),artist_composition_jsd=double());list(comparisons=result,vocabulary=data.frame(word=vocabulary),word_mass=w)
}
expected_richness<-function(counts,m){if(!is.numeric(counts)||any(!is.finite(counts))||any(counts<=0)||any(counts!=floor(counts)))stop('Counts must be positive integers');if(length(m)!=1||!is.finite(m)||m<0||m!=floor(m))stop('m must be a nonnegative integer');n<-sum(counts);if(m>n)return(NA_real_);absent_log<-rep(-Inf,length(counts));possible<-n-counts>=m;absent_log[possible]<-lchoose(n-counts[possible],m)-lchoose(n,m);sum(-expm1(absent_log))}
monthly_diversity<-function(events,m=500L){dplyr::bind_rows(lapply(split(events,events$end_month_utc),function(e){a<-as.numeric(table(e$artist));p<-a/sum(a);data.frame(month=e$end_month_utc[1],known_records=nrow(e),observed_artists=length(a),artist_effective_number=exp(-sum(p*log(p))),observed_pairs=length(unique(e$pair_id)),rarefaction_m=m,expected_pairs=expected_richness(as.numeric(table(e$pair_id)),m))}))}
cooccurrence_edges<-function(tokens,cfg){f<-dplyr::count(tokens[!tokens$word %in% c(cfg$stopwords,cfg$metadata_words)&stringr::str_length(tokens$word)>=cfg$content_min_chars,],word,name='pairs');f<-utils::head(dplyr::arrange(f,dplyr::desc(pairs),word),cfg$graph_top_words);z<-tokens[tokens$word %in% f$word,];edges<-dplyr::inner_join(z,z,by='pair_id',suffix=c('_a','_b'),relationship='many-to-many');edges<-dplyr::count(edges[edges$word_a<edges$word_b,],word_a,word_b,name='shared_pairs');edges$pairs_a<-f$pairs[match(edges$word_a,f$word)];edges$pairs_b<-f$pairs[match(edges$word_b,f$word)];edges$jaccard<-edges$shared_pairs/(edges$pairs_a+edges$pairs_b-edges$shared_pairs);edges[edges$shared_pairs>=cfg$graph_min_pairs,]}
analysis_theme<-function(){ggplot2::theme_minimal(base_size=12)+ggplot2::theme(panel.grid.minor=ggplot2::element_blank(),plot.title.position='plot',plot.title=ggplot2::element_text(face='bold'),legend.position='top')}
plot_presence<-function(x){ggplot2::ggplot(x,ggplot2::aes(word,100*proportion,color=weighting,group=weighting))+ggplot2::geom_point(position=ggplot2::position_dodge(width=.35),size=3)+ggplot2::facet_wrap(~scope)+ggplot2::scale_color_manual(values=c('#254B62','#C06B3E'))+ggplot2::labs(title='Repetition changes the title-language profile',x=NULL,y='Word presence (%)',color=NULL)+analysis_theme()}
plot_salience<-function(x,n=10L){z<-dplyr::bind_rows(utils::head(x,n),utils::tail(x,n)) |> dplyr::distinct(word,.keep_all=TRUE);ggplot2::ggplot(z,ggplot2::aes(log2_ratio,stats::reorder(word,log2_ratio)))+ggplot2::geom_vline(xintercept=0,color='grey70')+ggplot2::geom_segment(ggplot2::aes(x=0,xend=log2_ratio,yend=word),color='#A2BBC8')+ggplot2::geom_point(ggplot2::aes(size=title_pairs),color='#254B62')+ggplot2::labs(title='Words amplified or reduced by repeated listening',x='Smoothed log2(record presence / pair presence)',y=NULL,size='Distinct pairs')+analysis_theme()}
plot_drift<-function(x){x<-x[x$include_comparison,];z<-tidyr::pivot_longer(x,cols=c('vocabulary_jsd','pair_composition_jsd','artist_composition_jsd'),names_to='measure',values_to='jsd');z$date<-as.Date(paste0(z$month,'-01'));ggplot2::ggplot(z,ggplot2::aes(date,jsd,color=measure))+ggplot2::geom_line(linewidth=.7)+ggplot2::geom_point(size=2)+ggplot2::scale_color_manual(values=c('#C06B3E','#71836A','#254B62'))+ggplot2::scale_y_continuous(limits=c(0,1))+ggplot2::labs(title='Adjacent-month vocabulary and repertoire change',x=NULL,y='Jensen–Shannon divergence (bits)',color=NULL)+analysis_theme()}
plot_diversity<-function(x){z<-tidyr::pivot_longer(x,cols=c('artist_effective_number','expected_pairs'),names_to='measure',values_to='value');z$date<-as.Date(paste0(z$month,'-01'));ggplot2::ggplot(z,ggplot2::aes(date,value))+ggplot2::geom_line(color='#254B62',linewidth=.8)+ggplot2::geom_point(color='#C06B3E',size=2)+ggplot2::facet_wrap(~measure,scales='free_y',ncol=1)+ggplot2::labs(title='Diversity beyond raw repertoire size',x=NULL,y=NULL)+analysis_theme()}
analyze_history<-function(raw,cfg){h<-prepare_history(raw);tok<-title_tokens(h$pairs);list(audit=h$audit,primary=primary_presence(h$events,h$pairs,tok,cfg$primary_words,cfg$min_ms),salience=word_salience(h$events,h$pairs,tok,cfg),drift=monthly_drift(h$events,tok,cfg),diversity=monthly_diversity(h$events,cfg$rarefaction_m),edges=cooccurrence_edges(tok,cfg),annotation=annotation_sensitivity(h$events,h$pairs,cfg))}
strip_version_suffix<-function(title){tag<-'(?:live|remaster(?:ed)?|[0-9]{4}\\s+remaster(?:ed)?)';parenthetical<-paste0('(?i)\\s*\\(',tag,'\\b[^()]*\\)\\s*$');dashed<-paste0('(?i)\\s+[-–—]\\s+',tag,'\\b.*$');result<-stringr::str_remove(stringr::str_remove(title,parenthetical),dashed);ifelse(result!=title,stringr::str_trim(result),title)}
annotation_sensitivity<-function(events,pairs,cfg){cleaned<-pairs;cleaned$title<-strip_version_suffix(pairs$title);changed<-cleaned$title!=pairs$title;full<-word_salience(events,pairs,title_tokens(pairs),cfg);reduced<-word_salience(events,cleaned,title_tokens(cleaned),cfg);full$display_condition<-rep('full_display',nrow(full));reduced$display_condition<-rep('version_suffix_removed',nrow(reduced));examples<-data.frame(pair_id=pairs$pair_id[changed],artist=pairs$artist[changed],full_display=pairs$title[changed],version_suffix_removed=cleaned$title[changed]);counts<-data.frame(distinct_pairs=nrow(pairs),changed_pairs=sum(changed),known_records=nrow(events),changed_records=sum(events$pair_id %in% pairs$pair_id[changed]));comparison<-dplyr::full_join(full[,c('word','title_pairs','records','log2_ratio')],reduced[,c('word','title_pairs','records','log2_ratio')],by='word',suffix=c('_full_display','_version_suffix_removed'));comparison$log2_ratio_change<-comparison$log2_ratio_version_suffix_removed-comparison$log2_ratio_full_display;list(counts=counts,examples=examples,salience=dplyr::bind_rows(full,reduced),comparison=comparison)}
